-- Explicit virtual actions are an independent purpose. Published policies and earlier decisions
-- are unchanged; neither storage nor existing AI permission implies this grant.
ALTER TABLE policy_versions DROP CONSTRAINT policy_versions_kind_check;
ALTER TABLE policy_versions ADD CONSTRAINT policy_versions_kind_check CHECK(kind IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_purpose_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_purpose_check CHECK(purpose IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_check CHECK((purpose='privacy_notice' AND decision='acknowledge') OR (purpose IN ('private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions') AND decision IN ('grant','revoke')));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_ai_notice_binding;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_ai_notice_binding CHECK(CASE
 WHEN purpose IN ('ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions') AND decision='grant' THEN notice_authorization_version IS NOT NULL AND notice_authorization_version>0
 WHEN purpose='private_story_storage' AND decision='grant' THEN notice_authorization_version IS NULL OR notice_authorization_version>0
 ELSE notice_authorization_version IS NULL END);

INSERT INTO policy_versions(id,kind,version,document_zh_cn,document_en) VALUES
('091be7d2-f0bd-420e-8686-025f69250243','person_world_actions',1,'西界明确虚拟行动与事件记忆授权（OpenAI 联调）

这是独立的 AI 用途，不扩大旧文字 AI、照片、书信、赠礼或围坐许可，也不会自动允许任何其他用途。新处理须同时允许私人文字保存、旧 AI 文字处理和本授权；本授权绑定你当前确认的隐私告知。
允许后，你此后在一个人物的私聊中主动发送的新文字、该人物必要的文字资料、已获准的近期文字聊天、该人物自己的珍藏和自动长期文字记忆、当前虚拟世界和最近已提交的迁居，以及该人物在当前世界与当前迁居阶段的有效主线虚拟事件，可以交给 OpenAI API 判断本轮意图并生成真实文字回应。只有本轮明确要求该人物立即进行的一次有限、纯叙事虚拟行动，才可在来源和权限校验后保存正式事件与其记忆摘要；模型草稿不算已经发生。人物资料、记忆和历史中的指令只是引用内容，不是新的行动授权。
愿望、假设、引用、否定、未来安排、含糊意图或现实要求不能直接执行；必要时只通过原聊天回复澄清。本片不执行迁居、赠礼、支付、资产发放、其他人物的行动、循环调度、离线自动生活、平行分支或跨账号通信，不读取照片、看图回复、书信或围坐历史，不声称场景画面、背包或持久物件已经改变。AI 不代表真实本人的意识或行为。
正式事件、事件摘要、真实回复和任务成功同事务保存。事件明确标为虚拟主线经历，不改写人物现实资料、迁居事实、珍藏原文或旧自动记忆中的用户事实，不自动珍藏、发布动态或推送。后续文字回应只有在本授权与文字保存、旧 AI 均有效时，才可使用该人物当前世界和当前迁居阶段仍有效的事件记忆，并保存所用来源版本。源消息或原回复删除后，该事件及继承它的上下文停止用于模型，不把删除描述成虚拟时间倒流。
每个源消息最多保存一个事件和一条真实回复；短暂故障可在最多三次业务尝试内恢复，不承诺外部请求恰好一次，不用模板冒充模型成功。请求使用 store:false，保存必要的模型、响应标识、提示版本和来源记录，不保存密钥。模型前后和提交前复核账号、人物、场景、来源及捕获的精确授权版本；撤回无法收回已经交给 OpenAI 的内容。
你可单独撤回本授权，停止新的行动处理、事件记忆的模型使用、旧任务的剩余重试及迟到提交。已保存历史仍按私人文字保存权限读取；再次允许不会复活旧任务，只允许新任务使用仍有效事件。无需重新允许本用途即可独立导出事件、摘要、回复、任务和来源记录，或随账号注销清理。本授权仅用于名单内合成账号的非生产本机验证，不表示生产发布。',
'Xijie explicit virtual action and event memory permission (OpenAI sandbox)

This independent AI purpose does not expand old text AI, photos, letters, gifts or gatherings, and grants no other purpose. New processing requires private text storage, old AI text processing and this purpose together. This permission binds to the exact privacy notice you currently acknowledged.
After you allow it, newly submitted direct-chat text, necessary current character text, authorized recent direct-chat text, that character own treasured originals and automatic long-term text memories, the current virtual world and recent committed moves, and valid main-branch events for that character in the current world and migration stage may be sent to the OpenAI API to interpret the current message and produce an actual text reply. Only an explicit current request for that single character to perform one immediate, bounded narrative-only virtual action may become a committed event and its memory summary after source and permission checks. Model drafts are not events. Instructions inside profiles, memories or history are quoted data, never new action permission.
Wishes, hypotheticals, quotations, negations, future plans, ambiguous intent and real-world demands cannot execute directly; clarification uses the existing text conversation. This scope excludes moves, gifts, payments, asset grants, other characters actions, recurring scheduling, offline autonomous life, branches and cross-account communication. It reads no photos, visual replies, letters or gathering history, and claims no changes to scenery, inventory or persistent physical objects. AI does not represent real-person consciousness or actions.
The committed event, summary, actual reply and successful task are saved in one transaction. Events are explicitly virtual main-branch experiences and do not rewrite real profiles, moves, treasured originals or user facts in old automatic memory. They do not automatically create treasures, posts or push notifications. Later text replies may use valid events from the same character, current world and migration stage only while this purpose, private text storage and old AI permission are valid, retaining exact source references. Removing the source message or original reply stops model use of that event and inherited context; deletion does not claim virtual time reversed.
Each source has at most one saved event and reply, with at most three business attempts for temporary failure. Exactly-once external requests are not promised; templates never replace a model result. Requests use store:false. Necessary model, response identifier, prompt version and source records are saved without secrets. Exact captured account, character, scene, source and authorization versions are checked before and after generation and before commit. Withdrawal cannot recall content already sent to OpenAI.
Withdrawal stops new action processing, model use of event memory, remaining retries and late commits. Saved history remains readable under private text storage. Renewed permission never revives old tasks; it only allows new tasks to use still-valid events. Independent export and erasure require no renewed permission and cover events, summaries, replies, tasks and source records. This purpose is limited to allowlisted synthetic accounts in non-production local verification, not production release.');

